const thunderCrystalSheet=new Image();thunderCrystalSheet.assetSrc='assets/thunder-crystal-v1.png';
function thunderCrystalMark(e){return dist(e,p)<=500&&lineClear(e,p)?{x:p.x,y:p.y}:null;}
function beginThunderCrystal(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'thunderRecordedTriangle',bespoke:true,windup:1.8,origin:{x:e.x,y:e.y},marks:[thunderCrystalMark(e)],waves:0};}
function thunderCrystalLinks(a){let result=[];for(let i=0;i<(a.marks.length===2?1:a.marks.length);i++){let start=a.marks[i],end=a.marks[(i+1)%a.marks.length];if(start&&end&&lineClear(start,end))result.push([start,end]);}return result;}
function thunderCrystalNear(point,start,end){let dx=end.x-start.x,dy=end.y-start.y,d2=dx*dx+dy*dy,t=d2?Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/d2)):0;return Math.hypot(point.x-start.x-dx*t,point.y-start.y-dy*t)<=28+1e-8;}
const thunderCrystalAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e1')return thunderCrystalAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='thunderRecordedTriangle'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=360&&clear){beginThunderCrystal(e);return;}e.state='idle';if(d>800&&!e.aware||d<=220)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,72*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 while(a.marks.length<3&&e.elapsed>=a.marks.length*.5)a.marks.push(thunderCrystalMark(e));
 while(a.waves<2&&e.elapsed>=Math.round((1.8+a.waves*.6)*1e6)/1e6){a.waves++;e.struck=true;if(thunderCrystalLinks(a).some(([start,end])=>thunderCrystalNear(p,start,end)&&lineClear(start,p)&&lineClear(end,p)))hurt(46);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3){e.attack=null;e.state='idle';e.t=2.8;}
};
const thunderCrystalDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e1'||!thunderCrystalSheet.complete||!thunderCrystalSheet.naturalWidth||!thunderCrystalSheet.naturalHeight)return thunderCrystalDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='thunderRecordedTriangle')f={row:2,col:e.elapsed<1?0:e.elapsed<1.8?1:e.elapsed<2.6?2:3};let q=project(e.x,e.y),sw=thunderCrystalSheet.naturalWidth/4,sh=thunderCrystalSheet.naturalHeight/3,w=220,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,thunderCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*[.84,.84,.86][f.row],w,h);else ctx.drawImage(thunderCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*[.84,.84,.86][f.row],w,h);ctx.restore();return true;};
const thunderCrystalSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e1'?140:thunderCrystalSizeBase(e);
const thunderCrystalGroundBase=drawGroundEffects;drawGroundEffects=()=>{thunderCrystalGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e1'):enemies)){let a=e.attack;if(e.species!=='r6e1'||e.hp<=0||a?.pattern!=='thunderRecordedTriangle'||!visibleAt(e.x,e.y))continue;let fired=a.waves>0&&e.elapsed<1.8+(a.waves-1)*.6+.16;for(let point of a.marks)if(point)groundRing(point.x,point.y,28,fired?'#fff1c1':'#cba1ef',2);for(let [start,end]of thunderCrystalLinks(a)){let dx=end.x-start.x,dy=end.y-start.y,len=Math.hypot(dx,dy);if(len<.01)continue;let nx=-dy/len*28,ny=dx/len*28,points=[{x:start.x+nx,y:start.y+ny},{x:end.x+nx,y:end.y+ny},{x:end.x-nx,y:end.y-ny},{x:start.x-nx,y:start.y-ny}];ctx.save();ctx.fillStyle=fired?'#fff1c177':'#b689da22';ctx.strokeStyle=fired?'#fff1c1':'#cba1ef';ctx.lineWidth=fired?3:1;ctx.beginPath();points.forEach((point,i)=>{let q=project(point.x,point.y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}}};
